guided.solution:
CREATE MATERIALIZED VIEW category_counts AS
SELECT category_id, COUNT(*) AS products
FROM products
GROUP BY category_id;

UPDATE products SET category_id = 2 WHERE category_id = 1;

SELECT (SELECT products FROM category_counts WHERE category_id = 1) AS stored_in_view,
       (SELECT COUNT(*) FROM products WHERE category_id = 1) AS live_in_table;

